@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + researchKeywords : string[]
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
  + authors : Person[]
  + positionOfAuthor : int[]
}

interface PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
  + reviewer : Person
}

interface TechnicalReport extends ScientificArticle {
  + publisher : ResearchInstitution
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
  + publisher : Publisher
}

class ResearchInstitution {
  + institutionCode : int
  + journalSubscriptions : Journal[]
  + technicalReports : TechnicalReport[]
}

Person "1" -- "0..*" ScientificArticle : is author of
Person "1" -- "0..*" ScientificArticle : is reviewer of
ScientificArticle "1" -- "1" PeerReviewedPaper : or
ScientificArticle "1" -- "1" TechnicalReport : or
PeerReviewedPaper "1" -- "1" Journal : published in
TechnicalReport "1" -- "1" ResearchInstitution : published by

@enduml

